const mongoose = require('mongoose');

const cosReportSchema = new mongoose.Schema({
  branch_id: { 
    type: String, 
    required: true 
  },
  branch_name: { 
    type: String, 
    required: true 
  },
  bpoc_name: { 
    type: String, 
    required: true 
  },
  bpoc_mail: { 
    type: String, 
    required: true 
  },
  fileName: { 
    type: String, 
    default: 'Unknown/No file' 
  },
  // Using Mixed type to store the complex JSON error object generated by the frontend
  errorDetails: { 
    type: mongoose.Schema.Types.Mixed,
    default: null
  },
  sender_message: { 
    type: String, 
    required: true 
  },
  admin_message: { 
    type: String, 
    default: null 
  },
  isSolved: { 
    type: Boolean, 
    default: false 
  },
  filehash: {
  type: String,
//   required: false
},
  date: { 
    type: Date, 
    default: Date.now 
  }
});

module.exports = mongoose.model('CosReport', cosReportSchema);